from copy import deepcopy

def step(title,body='',prompt='',expect='',cmd='',where='Hermes Desktop chat in the Kopi Kaki workspace'):
 d=dict(title=title,body=body,expect=expect)
 if prompt:d.update(prompt=prompt,where=where)
 if cmd:d['cmd']=cmd
 return d

