 result=[a1,a2,a3,a4,a5,a6,a7,a8]
 def replace(x):
  if isinstance(x,str):return x.replace('outputs/lab04/','outputs/team/').replace('outputs/lab03','outputs/lab04').replace('PP Q2','PP Task 3').replace('PP Task 2; read the actual candidate','PP Task 3; read the actual candidate').replace('Lab 2 morning','Activities 2–3 morning')
  if isinstance(x,list):return [replace(y) for y in x]
  if isinstance(x,tuple):return tuple(replace(y) for y in x)
  if isinstance(x,dict):return {k:replace(v) for k,v in x.items()}
  return x
 labs[:]=[replace(x) for x in result]
